HEX64 = re.compile(r"[0-9a-f]{64}")


class ScientificSuccessorContractError(RuntimeError):
    """The frozen successor source, lineage, or authority changed."""


def require(condition: bool, message: str) -> None:
    if not condition:
        raise ScientificSuccessorContractError(message)


def canonical_bytes(value: Any) -> bytes:
    return json.dumps(value, sort_keys=True, separators=(",", ":"),
                      ensure_ascii=True, allow_nan=False).encode("ascii")


def digest(value: Any) -> str:
    return hashlib.sha256(canonical_bytes(value)).hexdigest()


def file_sha256(path: Path, block_size: int = 8 << 20) -> str:
    result = hashlib.sha256()
    with path.open("rb") as source:
        for block in iter(lambda: source.read(block_size), b""):
            result.update(block)
    return result.hexdigest()


def read_json(path: Path, label: str) -> dict[str, Any]:
    require(path.is_file() and not path.is_symlink(),
            f"{label} is absent or non-regular")
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ScientificSuccessorContractError(f"{label} is invalid JSON") from exc
    require(isinstance(value, dict), f"{label} is not an object")
    return value


def validate_signed(value: Mapping[str, Any], key: str,
                    label: str) -> dict[str, Any]:
    result = dict(value)
    recorded = result.pop(key, None)
    require(isinstance(recorded, str) and HEX64.fullmatch(recorded) is not None
            and recorded == digest(result), f"{label} self digest changed")
    result[key] = recorded
    return result


def fit_only_ledger() -> list[dict[str, Any]]:
    compressed = base64.b85decode(FIT_ONLY_LEDGER_B85.encode("ascii"))
    require(hashlib.sha256(compressed).hexdigest()
            == FIT_ONLY_LEDGER_COMPRESSED_SHA256,
            "fit-only ledger compressed bytes changed")
    try:
        value = json.loads(zlib.decompress(compressed).decode("ascii"))
    except (ValueError, UnicodeError, json.JSONDecodeError, zlib.error) as exc:
        raise ScientificSuccessorContractError("fit-only ledger is invalid") from exc
    require(isinstance(value, list) and len(value) == FIT_ROWS
            and digest(value) == FIT_ONLY_LEDGER_DIGEST,
            "fit-only ledger content changed")
    required = {"branch_identity_digest", "training_view_row_digest",
                "latent_sha256", "latent_byte_count"}
    require(all(isinstance(row, dict) and set(row) == required
                and all(isinstance(row[key], str) and HEX64.fullmatch(row[key])
                        for key in required - {"latent_byte_count"})
                and row["latent_byte_count"] == 6_291_456
                for row in value), "fit-only ledger schema changed")
    require(len({row["branch_identity_digest"] for row in value}) == FIT_ROWS
            and len({row["training_view_row_digest"] for row in value}) == FIT_ROWS,
            "fit-only ledger identities are duplicated")
    return value


def _git(root: Path, *arguments: str) -> str:
    try:
        return subprocess.check_output(
            ["git", *arguments], cwd=root, text=True,
            stderr=subprocess.STDOUT).strip()
    except (OSError, subprocess.CalledProcessError) as exc:
        raise ScientificSuccessorContractError(
            f"cannot bind successor source: {exc}") from exc


def source_closure(root: Path = ROOT) -> dict[str, Any]:
    require(_git(root, "status", "--porcelain=v1") == "",
            "successor source must be clean and committed")
    head = _git(root, "rev-parse", "HEAD")
    require(subprocess.run(
        ["git", "merge-base", "--is-ancestor", BASE_SOURCE_COMMIT, head],
        cwd=root, stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL).returncode == 0,
        "successor source does not descend from its base")
    changed = tuple(sorted(filter(None, _git(
        root, "diff", "--name-only", f"{BASE_SOURCE_COMMIT}..{head}"
    ).splitlines())))
    require(changed == tuple(sorted(NEW_SOURCE_PATHS)),
            "committed successor diff is not exactly four additive paths")
    frozen = {}
    for relative, (sha, size) in FROZEN_DEPENDENCY_FILES.items():
        path = root / relative
        require(path.is_file() and not path.is_symlink()
                and path.stat().st_size == size and file_sha256(path) == sha,
                f"frozen dependency changed: {relative}")
        frozen[relative] = {"sha256": sha, "byte_count": size}
    additive = {}
    for relative in NEW_SOURCE_PATHS:
        path = root / relative
        require(path.is_file() and not path.is_symlink(),
                f"additive source is absent: {relative}")
        additive[relative] = {
            "sha256": file_sha256(path), "byte_count": path.stat().st_size}
    payload = {
        "schema": SOURCE_SCHEMA, "source_repository_commit": head,
        "source_repository_clean": True,
        "base_source_commit": BASE_SOURCE_COMMIT,
        "exact_committed_additive_path_diff": list(changed),
        "frozen_dependency_files": frozen, "additive_files": additive,
    }
    return {**payload, SOURCE_SELF_KEY: digest(payload)}


def predecessor_root(root: Path = ROOT) -> Path:
    return root / PREDECESSOR_RUNTIME_RELATIVE


def runtime_root(root: Path = ROOT) -> Path:
    return root / RUNTIME_RELATIVE


def contract_path(root: Path = ROOT) -> Path:
    return root / CONTRACT_RELATIVE


def storage_binding(root: Path = ROOT) -> dict[str, Any]:
    logical = root / GENERATED_PARENT
    require(logical.is_symlink() and logical.resolve() == REGISTERED_PARENT,
            "registered generated-parent symlink changed")
    runtime = runtime_root(root)
    require(not runtime.exists() and not runtime.is_symlink(),
            "one-shot scientific namespace already exists")
    return {
        "logical_parent": str(GENERATED_PARENT),
        "registered_parent": str(REGISTERED_PARENT),
        "resolved_parent": str(logical.resolve()),
        "runtime_relative": str(RUNTIME_RELATIVE),
        "runtime_namespace_absent_before_issue": True,
    }


def validate_predecessor_success(root: Path = ROOT) -> dict[str, Any]:
    """Independently bind the exact diagnostic bytes and semantic success."""

    from scripts import (  # local import keeps the contract source-only
        diagnose_go2_attentive_readout_layernorm_affine_externalisation_v1
        as RUNNER,
    )
    base = predecessor_root(root)
    names = {
        "contract": ("contract.json", LN.CONTRACT_SELF_KEY,
                     "installed_contract", "installed_contract_digest"),
        "attempt": ("attempt.json", RUNNER.ATTEMPT_KEY,
                    "attempt", "attempt_digest"),
        "reproduction": ("reproduction.json", RUNNER.REPRODUCTION_KEY,
                         "reproduction", "reproduction_digest"),
        "local_cases": ("local_cases.json", RUNNER.LOCAL_KEY,
                        "local_cases", "local_cases_digest"),
        "conditional_smoke": ("conditional_whole_model_smoke.json",
                              RUNNER.SMOKE_KEY, "conditional_smoke",
                              "conditional_smoke_digest"),
        "terminal": ("terminal.json", RUNNER.TERMINAL_KEY,
                     "terminal", "terminal_digest"),
    }
    loaded = {}
    for name, (filename, key, file_prefix, binding_key) in names.items():
        path = base / filename
        expected_sha = PREDECESSOR_BINDING[f"{file_prefix}_file_sha256"]
        expected_size = PREDECESSOR_BINDING[f"{file_prefix}_byte_count"]
        value = validate_signed(read_json(path, f"predecessor {name}"),
                                key, f"predecessor {name}")
        require(path.stat().st_size == expected_size
                and file_sha256(path) == expected_sha
                and value[key] == PREDECESSOR_BINDING[binding_key],
                f"predecessor {name} bytes changed")
        loaded[name] = value
    validated = RUNNER.validate_terminal(root)
    require(validated == loaded["terminal"],
            "predecessor semantic validator disagrees")
    terminal = loaded["terminal"]
    smoke = loaded["conditional_smoke"]
    local = loaded["local_cases"]
    require(terminal.get("terminal_kind") == "SUCCESS_CLASSIFICATION"
            and terminal.get("mechanism_classification")
            == PREDECESSOR_BINDING["mechanism_classification"]
            and terminal.get("implementation_successor_eligibility")
            == LN.IMPLEMENTATION_NAME
            and terminal.get("training_authorised_now") is False
            and terminal.get("repair_authorised_now") is False
            and RUNNER.recompute_local_success(local)
            and RUNNER.recompute_smoke_success(smoke),
            "predecessor did not establish successor eligibility")
    checkpoint_path = base / "conditional_whole_model_smoke_checkpoint.pt"
    require(checkpoint_path.is_file() and not checkpoint_path.is_symlink()
            and checkpoint_path.stat().st_size
            == PREDECESSOR_BINDING["conditional_smoke_checkpoint_byte_count"]
            and file_sha256(checkpoint_path)
            == PREDECESSOR_BINDING["conditional_smoke_checkpoint_sha256"],
            "predecessor checkpoint bytes changed")
    # Torch content and every gradient gate are independently consumed by the
    # predecessor validator above; bind the primitive evidence again here.
    require(smoke.get("implementation_digest") == LN.IMPLEMENTATION_DIGEST
            and smoke.get("passed") is True
            and smoke.get("all_parameter_gradients_finite") is True
            and len(smoke.get("parameter_gradient_inventory", []))
            == LN.TRAINABLE_PARAMETER_TENSOR_COUNT
            and smoke.get("completed_optimizer_updates") == 1
            and smoke.get("calibration_rows_opened") == 0,
            "predecessor checkpoint/gradient evidence changed")
    return dict(PREDECESSOR_BINDING)


