def build_contract(source: Mapping[str, Any], predecessor: Mapping[str, Any],
                   storage: Mapping[str, Any]) -> dict[str, Any]:
    require(source.get("schema") == SOURCE_SCHEMA
            and source.get(SOURCE_SELF_KEY)
            == digest({k: v for k, v in source.items() if k != SOURCE_SELF_KEY}),
            "source closure changed")
    require(dict(predecessor) == PREDECESSOR_BINDING,
            "predecessor binding changed")
    require(storage.get("runtime_namespace_absent_before_issue") is True
            and storage.get("runtime_relative") == str(RUNTIME_RELATIVE)
            and storage.get("resolved_parent") == str(REGISTERED_PARENT),
            "storage binding changed")
    payload = {
        "schema": CONTRACT_SCHEMA, "source_closure": dict(source),
        "predecessor": dict(predecessor), "storage": dict(storage),
        **static_contract(),
    }
    return {**payload, CONTRACT_SELF_KEY: digest(payload)}


def validate_contract(value: Mapping[str, Any]) -> dict[str, Any]:
    result = validate_signed(value, CONTRACT_SELF_KEY, "successor contract")
    require(result == build_contract(result["source_closure"],
                                     result["predecessor"], result["storage"]),
            "successor contract changed")
    return result


